#include "stdlib/stats/base/ndarray/snanmskmin.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/ndarray/dtypes.h"
#include "stdlib/ndarray/orders.h"
#include "stdlib/ndarray/index_modes.h"
#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <math.h>
#include <sys/time.h>

/**
* Prints the TAP version.
*/
static void print_version( void ) {
	printf( "TAP version 13\n" );
}

/**
* Prints the TAP summary.
*
* @param total     total number of tests
* @param passing   total number of passing tests
*/
static void print_summary( int total, int passing ) {
	printf( "#\n" );
	printf( "1..%d\n", total );
	printf( "# total %d\n", total );
	printf( "# pass  %d\n", passing );
	printf( "#\n" );
	printf( "# ok\n" );
}

/**
* Prints benchmarks results.
*
* @param iterations   number of iterations
* @param elapsed      elapsed time in seconds
*/
static void print_results( int iterations, double elapsed ) {
	double rate = (double)iterations / elapsed;
	printf( "  ---\n" );
	printf( "  iterations: %d\n", iterations );
	printf( "  elapsed: %g\n", elapsed );
	printf( "  rate: %g\n", rate );
	printf( "  ...\n" );
}

/**
* Returns a clock time.
*
* @return clock time
*/
static double tic( void ) {
	struct timeval now;
	gettimeofday( &now, NULL );
	return (double)now.tv_sec + (double)now.tv_usec / 1.0e6;
}

/**
* Generates a random number on the interval [0,1).
*
* @return random number
*/
static float rand_float( void ) {
	return (float)rand() / ( (float)RAND_MAX + 1.0f );
}

/**
* Runs a benchmark.
*
* @param iterations   number of iterations
* @param len          array length
* @return             elapsed time in seconds
*/
static double benchmark( int iterations, int len ) {
	float *x;
	uint8_t *mask;
	int i;
	double t;
	double elapsed;

	x = (float *)malloc( len * sizeof( float ) );
	mask = (uint8_t *)malloc( len * sizeof( uint8_t ) );
	if ( x == NULL || mask == NULL ) {
		printf( "unable to allocate memory\n" );
		exit( 1 );
	}
	for ( i = 0; i < len; i++ ) {
		x[ i ] = ( rand_float() * 20.0f ) - 10.0f;
		mask[ i ] = ( rand_float() < 0.2f ) ? 1 : 0;
	}

	int64_t shape[] = { len };
	int64_t strides[] = { 1 };
	int64_t mstrides[] = { 1 };

	// cppcheck-suppress invalidPointerCast
	struct ndarray *X = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT32, (uint8_t *)x, 1, shape, strides, 0, STDLIB_NDARRAY_ROW_MAJOR, STDLIB_NDARRAY_INDEX_ERROR, 1, (int8_t[]){ STDLIB_NDARRAY_INDEX_ERROR } );
	// cppcheck-suppress invalidPointerCast
	struct ndarray *Mask = stdlib_ndarray_allocate( STDLIB_NDARRAY_UINT8, (uint8_t *)mask, 1, shape, mstrides, 0, STDLIB_NDARRAY_ROW_MAJOR, STDLIB_NDARRAY_INDEX_ERROR, 1, (int8_t[]){ STDLIB_NDARRAY_INDEX_ERROR } );

	const struct ndarray *arrays[] = { X, Mask };

	float v = 0.0f;
	t = tic();
	for ( i = 0; i < iterations; i++ ) {
		v = stdlib_stats_snanmskmin( arrays );
		if ( v != v ) {
			printf( "should not return NaN\n" );
			break;
		}
	}
	elapsed = tic() - t;
	if ( v != v ) {
		printf( "should not return NaN\n" );
	}
	stdlib_ndarray_free( X );
	stdlib_ndarray_free( Mask );

	return elapsed;
}

/**
* Main execution sequence.
*/
int main( void ) {
	double elapsed;
	int count;
	int iter;
	int len;
	int i;

	// Use a reproducible random seed:
	srand( 1 );

	print_version();
	count = 0;
	for ( i = 1; i <= 6; i++ ) {
		len = (int)pow( 10, i );
		iter = 1000000 / (int)pow( 10, i-1 );
		printf( "# c::%s:len=%d\n", "snanmskmin", len );
		elapsed = benchmark( iter, len );
		print_results( iter, elapsed );
		printf( "ok %d benchmark finished\n", ++count );
	}
	print_summary( count, count );

	return 0;
}
